fn primitive_pop(
    values: &mut Vec<Value>,
    operand_base: usize,
    operation: &mut SwiftExecutionOperation<'_>,
) -> Result<Value, SwiftRunFailure> {
    operation.control.work_with_wasi(
        Work::Execution,
        1,
        operation.cursor,
        Some(operation.wasi.usage()),
    )?;
    primitive_values_match(values, operation)?;
    if values.len() <= operand_base {
        return Err(primitive_invariant(operation));
    }
    let value = values.pop().expect("checked operand exists");
    operation
        .control
        .remove_live_with_wasi(Live::Values, 1, Some(operation.wasi.usage()))?;
    Ok(value)
}

fn control_remove(&mut self, resource: Live, amount: usize) -> Result<(), SwiftRunFailure> {
    let result = self.phase.operation.control.remove_live_with_wasi(
        resource,
        amount,
        Some(self.phase.operation.wasi.usage()),
    );
    if result.is_err() {
        self.cleanup.live_unreconciled = true;
    }
    result
}

pub(crate) fn control_operation(
    &mut self,
    operation: Operation,
    selected_target: Option<u32>,
) -> Result<bool, SwiftRunFailure> {
    let result = self.control_operation_inner(operation, selected_target);
    if result.is_err() {
        self.terminal();
    }
    result
}

fn terminal(&mut self) {
    *self.lifecycle = Lifecycle::Terminal;
    if self.cleanup.disposition == FrameDisposition::Active {
        self.cleanup.disposition = FrameDisposition::Draining;
        self.cleanup.unvisited = self.phase.parts.frames.len();
    }
}
fn active(&mut self) -> Result<(), SwiftRunFailure> {
    if self.cleanup.disposition != FrameDisposition::Active
        || matches!(self.lifecycle, Lifecycle::Terminal)
        || self.cleanup.entry.is_some()
        || self.cleanup.nested_restore.is_some()
        || self.cleanup.live_unreconciled
    {
        return Err(self.invariant("swift_frame_inactive"));
    }
    self.agreement()
